    const memberships = await db.select({ spaceId: Members.spaceId }).from(Members).where(eq(Members.userId, userId)).all();
    const ownedSpaceIds = await db.select({ id: Spaces.id }).from(Spaces).where(eq(Spaces.userId, userId)).all();
